"""Independent reference using FAdo automata operations (semantic cross-check)."""
import sys
sys.path[:0]=['/opt/emicro-deps','/workspace/project']
from FAdo.fa import DFA, NFA
from syntax import parse, MATCH, STARTSWITH, ENDSWITH, CONTAINS, AND, OR, NOT, ALLOW, DROP
from ebpf.create_dfa import create, registry_columns
DENY=4294967295

def atom_dfa(kind, cols, sigma):
    """Build the atom language DFA/NFA with FAdo primitives."""
    if kind==MATCH:
        d=DFA(); d.setSigma(sigma)
        for i in range(len(cols)+2): d.addState('q%d'%i)
        d.setInitial(0)
        dead=len(cols)+1
        for i in range(len(cols)):
            for c in sigma:
                d.addTransition(i, c, i+1 if c==cols[i] else dead)
        for c in sigma:
            d.addTransition(len(cols), c, dead); d.addTransition(dead,c,dead)
        d.addFinal(len(cols))
        return d
    if kind==STARTSWITH:
        d=DFA(); d.setSigma(sigma)
        for i in range(len(cols)+2): d.addState('q%d'%i)
        d.setInitial(0); dead=len(cols)+1
        for i in range(len(cols)):
            for c in sigma:
                d.addTransition(i, c, i+1 if c==cols[i] else dead)
        for c in sigma:
            d.addTransition(len(cols), c, len(cols)); d.addTransition(dead,c,dead)
        d.addFinal(len(cols))
        return d
    n=NFA(); n.setSigma(sigma)
    n.addState('s0'); n.setInitial([0])
    for c in sigma: n.addTransition(0,c,0)
    n.addState('e0'); n.addTransition(0,'@epsilon',1)
    for i,c in enumerate(cols):
        n.addState('s%d'%(i+1)); n.addTransition(i+1,c,i+2)
    n.addFinal(len(cols)+1)
    if kind==ENDSWITH:
        return n.toDFA()
    for c in sigma: n.addTransition(len(cols)+1,c,len(cols)+1)
    return n.toDFA()

def build(node, sigma, colmap, cache):
    k=node[0]
    if k<=CONTAINS:
        cols=tuple(node[1])
        key=(k,cols)
        if key not in cache: cache[key]=atom_dfa(k,cols,sigma)
        return cache[key]
    if k==AND: return build(node[1],sigma,colmap,cache) & build(node[2],sigma,colmap,cache)
    if k==OR: return build(node[1],sigma,colmap,cache) | build(node[2],sigma,colmap,cache)
    return ~build(node[1],sigma,colmap,cache)

def fado_image(text, cols, colmap):
    res=parse(text)
    names=res.names
    cols_of=[colmap[names[i]] for i in range(len(names))]
    sigma=set(cols)
    cache={}
    allow=None; drop=None
    for node,act in res.rules:
        n2=(_ren(node,cols_of))
        d=build(n2,sigma,colmap,cache)
        if act==ALLOW: allow = d if allow is None else (allow|d)
        else: drop = d if drop is None else (drop|d)
    if allow is None:
        lang=None
    elif drop is None:
        lang=allow
    else:
        lang=allow & (~drop)
    if lang is None:
        m=DFA(); m.setSigma(sigma); m.addState('d'); m.setInitial(0)
        for c in sigma: m.addTransition(0,c,0)
    else:
        m=lang.minimal()
    return canonical(m, cols)

def _ren(node, cols_of):
    k=node[0]
    if k<=CONTAINS: return (k, tuple(cols_of[i] for i in node[1]), None)
    if k==NOT: return (k,_ren(node[1],cols_of),None)
    return (k,_ren(node[1],cols_of),_ren(node[2],cols_of))

def canonical(m, cols):
    """Live-state pruning + BFS numbering from m (a complete minimal DFA)."""
    sigma=cols  # column order
    states=list(range(len(m.States)))
    delta={}
    for s in states:
        row=[]
        for c in sigma:
            t=m.delta.get(s,{}).get(c)
            row.append(t if t is not None else None)
        delta[s]=row
    # find dead class: states that cannot reach a final state
    fin=set(m.Final)
    live=set(fin)
    changed=True
    while changed:
        changed=False
        for s in states:
            if s in live: continue
            for t in delta[s]:
                if t is not None and t in live:
                    live.add(s); changed=True; break
    start=m.Initial
    if isinstance(start,(list,set,tuple)): start=list(start)[0]
    order=[start]; index={start:0}; head=0
    while head<len(order):
        s=order[head]; head+=1
        for t in delta[s]:
            if t is None or t not in live: continue
            if t not in index:
                index[t]=len(index); order.append(t)
    rows=[]
    for s in order:
        rows.append([index[t] if (t is not None and t in live) else DENY for t in delta[s]])
    accept=[(s in fin) for s in order]
    return {'accept':accept,'rows':rows}
